from collections import deque
import json

def find_connected_zero_components(grid):
    """Find all connected components of zeros"""
    visited = set()
    components = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 0 and (r, c) not in visited:
                component = []
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    component.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == 0 and (nr, nc) not in visited:
                                queue.append((nr, nc))
                components.append(component)
    return components

def transform(grid):
    """
    Transform rule:
    - Find connected components of zeros
    - Convert components with size >= 2 to 8s
    - Isolated zeros (size 1) stay 0
    - Non-zero cells stay unchanged
    """
    result = [row[:] for row in grid]
    components = find_connected_zero_components(result)

    for component in components:
        if len(component) >= 2:
            for r, c in component:
                result[r][c] = 8

    return result

